    /**
     * Method to retrieve the Account via AccountFetchOneSummary
     * @param 	summary AccountFetchOneSummary 
     * @return 	AccountFetchOneResponse
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    public Account getAccount( AccountFetchOneSummary summary ) 
    throws ProcessingException, IllegalArgumentException {
    	
    	if( summary == null )
    		throw new IllegalArgumentException( "AccountFetchOneSummary arg cannot be null" );
    	
    	Account entity = null;
    	
        try {
        	// --------------------------------------
        	// validate the fetch one summary
        	// --------------------------------------    	
        	validator.validate( summary );    
        	
        	// --------------------------------------
        	// use queryGateway to send request to Find a Account
        	// --------------------------------------
        	CompletableFuture<Account> futureEntity = queryGateway.query(new FindAccountQuery( new LoadAccountFilter( summary.getAccountId() ) ), ResponseTypes.instanceOf(Account.class));
        	
        	entity = futureEntity.get();
        }
        catch( Exception exc ) {
            final String errMsg = "Unable to locate Account with id " + summary.getAccountId();
            LOGGER.log( Level.WARNING, errMsg, exc );
            throw new ProcessingException( errMsg, exc );
        }
        finally {
        }        
        
        return entity;
    }


